pub fn graphemeProperties(cp: u21) GraphemeProperties {
    if (cp < grapheme_ascii.len) return grapheme_ascii[cp];
    var lo: usize = 0; var hi: usize = grapheme_ranges.len;
    while (lo < hi) { const mid = lo + (hi - lo) / 2; const r = grapheme_ranges[mid]; if (cp < r.lo) hi = mid else if (cp > r.hi) lo = mid + 1 else return r.properties; }
    return .{ .gcb = .other, .incb = .none, .extended_pictographic = false };
}

