pub fn lineBreak(cp: u21) LineBreak {
    if (cp < line_break_ascii.len) return line_break_ascii[cp];
    var lo: usize = 0; var hi: usize = line_break_ranges.len;
    while (lo < hi) { const mid = lo + (hi - lo) / 2; const r = line_break_ranges[mid]; if (cp < r.lo) hi = mid else if (cp > r.hi) lo = mid + 1 else return r.class; }
    return .xx;
}

fn inRanges(ranges: []const Range, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const r = ranges[mid];
        if (cp < r.lo) hi = mid else if (cp > r.hi) lo = mid + 1 else return true;
    }
    return false;
}
